args.command:
(npx vite --port 5173 --strictPort --host 127.0.0.1 > /tmp/vite.log 2>&1 &) ; sleep 6; cat /tmp/vite.log | tail -5; cd /tmp/shot && cat > launch.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({ args: ['--no-sandbox'] });
const p = await b.newPage();
await p.goto('http://127.0.0.1:5173/');
await p.waitForSelector('svg[role="img"]', { timeout: 15000 });
await p.screenshot({ path: '/tmp/shot/light.png', fullPage: true });
await b.close();
console.log('ok');
EOF
timeout 120 node launch.mjs 2>&1 | tail -15

